public class FastDateFormat_format_TriageGen0Test {

    @Test
    public void testFormat_WithTimeZoneForcedTrue() {
        // Setup: getInstance with a specific timezone. 
        // FastDateFormat internal 'mTimeZoneForced' is true when a TimeZone is provided via getInstance(pattern, timeZone)
        String pattern = "yyyy-MM-dd HH:mm:ss";
        TimeZone forcedZone = TimeZone.getTimeZone("UTC");
        FastDateFormat fdf = FastDateFormat.getInstance(pattern, forcedZone);

        // Verify flag via public method if available, or infer from behavior
        assertTrue("TimeZone should be overridden when provided to getInstance", fdf.getTimeZoneOverridesCalendar());

        // Create a calendar in a different timezone (e.g., GMT+8)
        Calendar calendar = Calendar.getInstance(TimeZone.getTimeZone("GMT+8"));
        calendar.set(2023, Calendar.OCTOBER, 27, 10, 0, 0);
        calendar.set(Calendar.MILLISECOND, 0);

        StringBuffer buf = new StringBuffer();

        // The method should clone the calendar and set it to UTC
        // 10:00 AM GMT+8 is 02:00 AM UTC
        fdf.format(calendar, buf);

        assertEquals("2023-10-27 02:00:00", buf.toString());
    }






}

