public class FastDateFormat_format_TriageGen0Test {



    @Test
    public void testFormat_WithTimeZoneForcedFalse() {
        // Setup: getInstance with default (no specific timezone provided)
        // In FastDateFormat, if no TimeZone is passed to getInstance, mTimeZoneForced is false
        String pattern = "yyyy-MM-dd HH:mm:ss";
        FastDateFormat fdf = FastDateFormat.getInstance(pattern);

        assertFalse("TimeZone should not be overridden when not specified", fdf.getTimeZoneOverridesCalendar());

        // Create a calendar in GMT+8
        Calendar calendar = Calendar.getInstance(TimeZone.getTimeZone("GMT+8"));
        calendar.set(2023, Calendar.OCTOBER, 27, 10, 0, 0);
        calendar.set(Calendar.MILLISECOND, 0);

        StringBuffer buf = new StringBuffer();

        // The method should use the calendar's own timezone
        fdf.format(calendar, buf);

        assertEquals("2023-10-27 10:00:00", buf.toString());
    }




}

