public class FastDateFormat_format_TriageGen0Test {







    @Test
    public void testFormat_WithDifferentLocale() {
        // Testing the applyRules behavior via locale-specific patterns
        String pattern = "MMMM"; // Full month name
        FastDateFormat fdf = FastDateFormat.getInstance(pattern, Locale.FRENCH);

        Calendar calendar = Calendar.getInstance();
        calendar.set(2023, Calendar.JANUARY, 1);

        StringBuffer buf = new StringBuffer();
        fdf.format(calendar, buf);

        // January in French is "janvier"
        assertEquals("janvier", buf.toString().toLowerCase());
    }
